  "answered": [
    {
      "id": "Q1",
      "title": "Q1 · 숫자가 아닌 입력",
      "answer": "amount 또는 percent가 숫자가 아니거나 NaN이면 RangeError를 던지고 해당 TC를 추가한다.",
      "source": "relayed"
